def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty.")

    # Select a solution with high potential for improvement
    objectives = np.array([obj for _, obj in archive])
    diversity = np.std(objectives, axis=0)
    scores = np.dot(objectives, diversity)
    selected_idx = np.argmax(scores)
    base_solution = archive[selected_idx][0].copy()

    current_weight = np.sum(weight_lst[base_solution == 1])
    new_solution = base_solution.copy()
    n_items = len(new_solution)

    # Step 1: Objective-aware adaptive selection
    if np.random.rand() < 0.6:
        obj_weight = np.random.rand()
        target_value = value1_lst if obj_weight > 0.5 else value2_lst
        included = np.where(new_solution == 1)[0]
        excluded = np.where(new_solution == 0)[0]

        if len(included) > 0 and len(excluded) > 0:
            for i in included:
                for j in excluded:
                    if current_weight - weight_lst[i] + weight_lst[j] <= capacity:
                        gain = (target_value[j] - target_value[i]) * (1 if obj_weight > 0.5 else -1)
                        if gain > 0:
                            new_solution[i] = 0
                            new_solution[j] = 1
                            current_weight = current_weight - weight_lst[i] + weight_lst[j]
                            break

    # Step 2: Dynamic perturbation based on solution quality
    solution_quality = np.mean(objectives[selected_idx])
    if np.random.rand() < 0.4 + 0.3 * solution_quality:
        num_perturbations = min(2, n_items)
        perturb_indices = np.random.choice(n_items, num_perturbations, replace=False)

        for idx in perturb_indices:
            if new_solution[idx] == 1:
                if current_weight - weight_lst[idx] >= 0:
                    new_solution[idx] = 0
                    current_weight -= weight_lst[idx]
            else:
                if current_weight + weight_lst[idx] <= capacity:
                    new_solution[idx] = 1
                    current_weight += weight_lst[idx]

    # Step 3: Greedy refinement for both objectives
    if np.random.rand() < 0.5:
        for _ in range(2):
            best_gain = 0
            best_idx = -1
            best_type = None

            for idx in np.where(new_solution == 0)[0]:
                if current_weight + weight_lst[idx] <= capacity:
                    combined_gain = value1_lst[idx] + value2_lst[idx]
                    if combined_gain > best_gain:
                        best_gain = combined_gain
                        best_idx = idx
                        best_type = 'add'

            for idx in np.where(new_solution == 1)[0]:
                if current_weight - weight_lst[idx] >= 0:
                    combined_gain = value1_lst[idx] + value2_lst[idx]
                    if combined_gain > best_gain:
                        best_gain = combined_gain
                        best_idx = idx
                        best_type = 'remove'

            if best_idx != -1 and best_gain > 0:
                if best_type == 'add':
                    new_solution[best_idx] = 1
                    current_weight += weight_lst[best_idx]
                else:
                    new_solution[best_idx] = 0
                    current_weight -= weight_lst[best_idx]

    return new_solution

def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty.")

    # Select solution with highest potential improvement
    objectives = np.array([obj for _, obj in archive])
    potential = np.sum(objectives, axis=1)  # Sum of objectives as improvement potential
    selected_idx = np.argmax(potential)
    base_solution = archive[selected_idx][0].copy()

    # Calculate current state
    current_weight = np.sum(weight_lst[base_solution == 1])
    current_value1 = np.sum(value1_lst[base_solution == 1])
    current_value2 = np.sum(value2_lst[base_solution == 1])

    # Initialize new solution
    new_solution = base_solution.copy()
    n_items = len(new_solution)

    # Phase 1: Value dominance analysis and dynamic weight adjustment
    if n_items > 0:
        # Calculate dominance scores
        dominance_scores = np.zeros(n_items)
        for i in range(n_items):
            if base_solution[i] == 1:
                # Items already in solution
                dominance_scores[i] = (value1_lst[i] + value2_lst[i]) / (weight_lst[i] + 1e-10)
            else:
                # Potential items to add
                if current_weight + weight_lst[i] <= capacity:
                    dominance_scores[i] = (value1_lst[i] + value2_lst[i]) / (weight_lst[i] + 1e-10)

        # Dynamic weight adjustment based on dominance
        max_dominance = np.max(dominance_scores) if np.max(dominance_scores) > 0 else 1
        weight1 = 0.5 + 0.4 * (np.sum(value1_lst[base_solution == 1]) / (np.sum(value1_lst) + 1e-10))
        weight2 = 0.5 - 0.4 * (np.sum(value2_lst[base_solution == 1]) / (np.sum(value2_lst) + 1e-10))

        # Probabilistic item reallocation
        for i in range(n_items):
            if base_solution[i] == 1:
                # Probability to remove based on dominance
                remove_prob = 0.3 * (1 - dominance_scores[i] / max_dominance)
                if np.random.rand() < remove_prob:
                    if current_weight - weight_lst[i] >= 0:
                        temp_weight = current_weight - weight_lst[i]
                        # Check if we can add better items
                        can_add = False
                        for j in range(n_items):
                            if base_solution[j] == 0 and temp_weight + weight_lst[j] <= capacity:
                                if (value1_lst[j] + value2_lst[j]) / (weight_lst[j] + 1e-10) > dominance_scores[i]:
                                    can_add = True
                                    break
                        if can_add:
                            new_solution[i] = 0
                            current_weight = temp_weight
            else:
                # Probability to add based on dominance and capacity
                if current_weight + weight_lst[i] <= capacity:
                    add_prob = 0.7 * (dominance_scores[i] / max_dominance)
                    if np.random.rand() < add_prob:
                        new_solution[i] = 1
                        current_weight += weight_lst[i]

    # Phase 2: Item clustering and probabilistic reallocation
    if n_items > 1:
        # Cluster items based on value ratios
        value_ratios = value1_lst / (value2_lst + 1e-10)
        clusters = np.digitize(value_ratios, bins=[np.percentile(value_ratios, 33), np.percentile(value_ratios, 66)])

        for cluster in range(1, 4):
            cluster_indices = np.where(clusters == cluster)[0]
            if len(cluster_indices) > 0:
                # Select a random item from the cluster
                idx = np.random.choice(cluster_indices)
                if new_solution[idx] == 1:
                    # Probability to remove based on cluster size
                    remove_prob = 0.4 * (1 - len(cluster_indices) / n_items)
                    if np.random.rand() < remove_prob:
                        if current_weight - weight_lst[idx] >= 0:
                            temp_weight = current_weight - weight_lst[idx]
                            # Check if we can add better items from other clusters
                            can_add = False
                            for j in range(n_items):
                                if new_solution[j] == 0 and temp_weight + weight_lst[j] <= capacity:
                                    if clusters[j] != cluster:
                                        can_add = True
                                        break
                            if can_add:
                                new_solution[idx] = 0
                                current_weight = temp_weight
                else:
                    # Probability to add based on cluster size and capacity
                    if current_weight + weight_lst[idx] <= capacity:
                        add_prob = 0.6 * (len(cluster_indices) / n_items)
                        if np.random.rand() < add_prob:
                            new_solution[idx] = 1
                            current_weight += weight_lst[idx]

    return new_solution
